144:     public synchronized Order manual(UUID id,LocalDate date,List<RawPayloadEvidence> pages) {
145:         Instant now=Instant.now();
146:         J3DatePolicy.requireCollectionDate(date,now);
147:         requireReady();
148:         Trigger trigger=pages==null?Trigger.MANUAL_PROVIDER:Trigger.MANUAL_IMPORT;
149:         String hash=null;
150:         if(pages!=null) {
151:             pages=J3LocalBatchValidator.validate(date,pages);hash=J3LocalBatchValidator.fingerprint(pages);
152:             if(!imports.containsKey(id) && imports.size()>=8) throw new IllegalStateException("J3_IMPORT_QUEUE_FULL");
153:         } else {
154:             String reason=providerUnavailableReason();if(reason!=null) throw new IllegalStateException(reason);
155:         }
156:         if(pages!=null) imports.put(id,pages);
157:         try {
158:             Order order=orders.manual(id,date,trigger,hash,owner,Instant.now());
159:             if(order.terminal()) imports.remove(id);
160:             wakeConsumer();return order;
161:         } catch(RuntimeException failure) {imports.remove(id);throw failure;}
162:     }
163:     public Settings configure(long revision,boolean enabled,Mode mode,LocalTime time) {
164:         return orders.configure(revision,enabled,mode,mode==Mode.DAILY_AT?time:null,Instant.now());
165:     }
166:     public Order schedule(UUID rule,int revision,LocalDate date,LocalDateTime at,ZoneOffset offset) {
167:         Instant now=Instant.now();
168:         J3DatePolicy.requireCollectionDate(date,now);
169:         J3DatePolicy.requirePlanTime(at,now);
170:         return orders.schedule(rule,revision,date,
171:                 com.bettingproject.sofascorelocal.domain.scheduledevents.J3AutomationData.resolveOneShot(at,offset),now);
172:     }
173:     public void cancel(UUID id) {orders.cancel(id,Instant.now());synchronized(this) {imports.remove(id);}}
174:     public void retryCleanup() {
175:         synchronized(cleanupMonitor) {
176:             if(pendingCleanup==null) throw new IllegalStateException("J3_NO_CLEANUP_PENDING");
177:             cleanupRequested=true;cleanupMonitor.notifyAll();
178:         }
179:     }
180:     private void requireReady() {
181:         if(!ready || stopping) throw new IllegalStateException(runtimeReason==null?"J3_RUNTIME_UNAVAILABLE":runtimeReason);
182:     }
183: 
184:     private void wakeConsumer() {
185:         if(consuming.compareAndSet(false,true)) consumer.execute(()->{
186:             try {
187:                 if(reconciliation!=null) {
188:                     Order unresolved=reconciliation;
189:                     if(!orders.find(unresolved.id()).orElseThrow().terminal())
190:                         completion.interrupt(unresolved.id(),unresolved.owner(),Instant.now(),"EXECUTION_INTERRUPTED");
191:                     reconciliation=null;
192:                 }
193:                 while(!stopping) {
194:                     Optional<Order> claimed=orders.claim(owner,Instant.now());
195:                     if(claimed.isEmpty()) break;
196:                     execute(claimed.orElseThrow());
197:                 }
198:                 synchronized(this) {
199:                     imports.keySet().removeIf(id->orders.find(id).map(Order::terminal).orElse(true));
200:                 }
201:             } catch(RuntimeException failure) {runtimeReason="J3_EXECUTION_RECONCILIATION_REQUIRED";}
202:             finally {consuming.set(false);}
203:         });
204:     }
