7: /** Scheduling identities use civil dates in Paris and store resolved instants separately. */
8: public final class J3AutomationData {
9:     public static final ZoneId ZONE=ZoneId.of("Europe/Paris");
10:     public static final Duration ORDER_DEADLINE=Duration.ofMinutes(20);
11:     public static final int MAXIMUM_PLANS=100;
12:     private J3AutomationData() { }
13:     public enum Mode { STARTUP_OR_DAY_CHANGE, DAILY_AT }
14:     public enum OrderState { FUTURE, QUEUED, RUNNING, COMPLETED, FAILED, CANCELLED, INTERRUPTED, MISSED, SKIPPED }
15:     public record Settings(boolean enabled,Mode mode,LocalTime dailyTime,long revision,Instant updatedAt) {
16:         public Settings {
17:             Objects.requireNonNull(mode);Objects.requireNonNull(updatedAt);
18:             if(revision<1 || (mode==Mode.DAILY_AT)!=(dailyTime!=null)
19:                     || dailyTime!=null && (dailyTime.getSecond()!=0 || dailyTime.getNano()!=0))
20:                 throw new IllegalArgumentException("J3_SETTINGS_INVALID");
21:         }
22:     }
23:     public record Owner(UUID id,long pid,Instant processStartedAt) {
24:         public Owner {Objects.requireNonNull(id);Objects.requireNonNull(processStartedAt);if(pid<1)throw new IllegalArgumentException("J3_OWNER_INVALID");}
25:     }
26:     public record Order(UUID id,String occurrenceKey,UUID ruleId,int ruleRevision,LocalDate date,Trigger trigger,
27:                         Instant dueAt,Instant createdAt,OrderState state,Instant admittedAt,Instant deadline,
28:                         Instant finishedAt,String reason,Owner owner,String inputSha256) {
29:         public Order {
30:             Objects.requireNonNull(id);Objects.requireNonNull(occurrenceKey);Objects.requireNonNull(date);
31:             Objects.requireNonNull(trigger);Objects.requireNonNull(dueAt);Objects.requireNonNull(createdAt);Objects.requireNonNull(state);
32:         }
33:         public boolean automatic() {return trigger.automatic();}
34:         public boolean terminal() {return state!=OrderState.FUTURE && state!=OrderState.QUEUED && state!=OrderState.RUNNING;}
35:     }
36:     /** One-shot wall times must exist; an overlap requires an explicit valid offset. */
37:     public static Instant resolveOneShot(LocalDateTime value,ZoneOffset selectedOffset) {
38:         Objects.requireNonNull(value);requireMinute(value.toLocalTime());
39:         var offsets=ZONE.getRules().getValidOffsets(value);
40:         if(offsets.isEmpty())throw new IllegalArgumentException("J3_TIME_DOES_NOT_EXIST");
41:         if(offsets.size()>1 && selectedOffset==null)throw new IllegalArgumentException("J3_TIME_OFFSET_REQUIRED");
42:         ZoneOffset offset=selectedOffset==null?offsets.getFirst():selectedOffset;
43:         if(!offsets.contains(offset))throw new IllegalArgumentException("J3_TIME_OFFSET_INVALID");
44:         return value.toInstant(offset);
45:     }
46:     /** A recurring gap advances to its transition; overlaps use the first instant exactly once. */
47:     public static Instant dailyOccurrence(LocalDate date,LocalTime time) {
48:         Objects.requireNonNull(date);requireMinute(time);
49:         var local=date.atTime(time);var rules=ZONE.getRules();var offsets=rules.getValidOffsets(local);
50:         return offsets.isEmpty()?rules.getTransition(local).getInstant():local.toInstant(offsets.getFirst());
51:     }
52:     public static String dailyKey(LocalDate date) {return "DAILY|"+date;}
53:     public static String timedKey(Settings settings,LocalDate date) {
54:         return "DAILY_AT|"+settings.revision()+"|"+date+"|"+dailyOccurrence(date,settings.dailyTime());
55:     }
56:     private static void requireMinute(LocalTime time) {
57:         Objects.requireNonNull(time);
58:         if(time.getSecond()!=0 || time.getNano()!=0)throw new IllegalArgumentException("J3_TIME_MINUTE_REQUIRED");
59:     }
60: }
