12: /** Durable J3 V7 results. The trigger is independent of each page's acquisition source. */
13: public final class J3CollectionData {
14:     private J3CollectionData() { }
15: 
16:     public enum Trigger {
17:         MANUAL_PROVIDER, MANUAL_IMPORT, DAILY, DAILY_AT, SCHEDULED, LEGACY;
18:         public boolean automatic() { return this == DAILY || this == DAILY_AT || this == SCHEDULED; }
19:     }
20:     public enum State { RUNNING, COMPLETED, FAILED, CANCELLED, INTERRUPTED }
21: 
22:     public record Proof(UUID runId, LocalDate date, Trigger trigger, Instant startedAt,
23:                         Instant finishedAt, State state, String terminalCode,
24:                         List<J3MinimizedPageEvidence> pages) {
25:         public Proof {
26:             Objects.requireNonNull(runId); Objects.requireNonNull(date); Objects.requireNonNull(trigger);
27:             Objects.requireNonNull(startedAt); Objects.requireNonNull(finishedAt); Objects.requireNonNull(state);
28:             pages = List.copyOf(pages);
29:             if (state == State.RUNNING || finishedAt.isBefore(startedAt) || pages.size() > 35
30:                     || terminalCode == null || !terminalCode.matches("[A-Z0-9_]{1,96}"))
31:                 throw new IllegalArgumentException("Invalid terminal J3 proof");
32:             for (int i = 0; i < pages.size(); i++)
33:                 if (pages.get(i).page() != i + 1) throw new IllegalArgumentException("Non-contiguous J3 pages");
34:             if (state == State.COMPLETED && (!"NONE".equals(terminalCode) || !complete(pages)))
35:                 throw new IllegalArgumentException("Incomplete J3 success");
36:             if (state != State.COMPLETED && "NONE".equals(terminalCode))
37:                 throw new IllegalArgumentException("Missing J3 terminal reason");
38:         }
39:         public boolean successful() { return state == State.COMPLETED; }
40:     }
41: 
42:     public static boolean complete(List<J3MinimizedPageEvidence> pages) {
43:         if (pages.isEmpty() || pages.size() > 35) return false;
44:         for (int i = 0; i < pages.size(); i++) {
45:             var p = pages.get(i);
46:             if (p.page() != i + 1 || !p.snapshotRecorded() || p.schemaStatus() != RawSnapshotSchemaStatus.PARSED
47:                     || p.httpStatus() < 200 || p.httpStatus() >= 300 || p.terminalCode() != null
48:                     || !Boolean.valueOf(i < pages.size() - 1).equals(p.hasNextPage())) return false;
49:         }
50:         return pages.stream().map(J3MinimizedPageEvidence::snapshotId).distinct().count() == pages.size();
51:     }
52: 
53:     public record Entry(long tournamentId, String name, String category, Long uniqueTournamentId,
54:                         String uniqueTournamentName, Map<Integer, Integer> timezoneEventCount,
55:                         List<Long> sourceSnapshotIds, String exclusionReason) {
56:         public Entry {
57:             if (tournamentId < 1 || name == null || (exclusionReason == null && (name.isBlank()
58:                     || name.chars().anyMatch(Character::isISOControl)))) throw new IllegalArgumentException("Invalid tournament");
59:             timezoneEventCount = Map.copyOf(timezoneEventCount); sourceSnapshotIds = List.copyOf(sourceSnapshotIds);
60:             if (sourceSnapshotIds.isEmpty() || sourceSnapshotIds.stream().anyMatch(id -> id == null || id < 1)
61:                     || sourceSnapshotIds.stream().distinct().count() != sourceSnapshotIds.size())
62:                 throw new IllegalArgumentException("Invalid tournament sources");
63:             if (exclusionReason != null && !exclusionReason.matches("[A-Z0-9_]{1,96}"))
64:                 throw new IllegalArgumentException("Invalid exclusion reason");
65:         }
66:         public boolean eligible() { return exclusionReason == null; }
67:         public J3TournamentCatalogOption option() {
68:             if (!eligible()) throw new IllegalStateException("Tournament is not eligible");
69:             return new J3TournamentCatalogOption(tournamentId, name, category, uniqueTournamentId,
70:                     uniqueTournamentName, timezoneEventCount, sourceSnapshotIds);
71:         }
72:     }
73: 
74:     public record Projection(J3TournamentCatalog catalog, List<Entry> entries) {
75:         public Projection { Objects.requireNonNull(catalog); entries = List.copyOf(entries); }
76:     }
77:     public record Collection(Proof proof, List<Entry> entries) {
78:         public Collection { Objects.requireNonNull(proof); entries = List.copyOf(entries); }
79:         public UUID id() { return proof.runId(); }
80:         public LocalDate date() { return proof.date(); }
81:         public J3TournamentCatalog catalog() {
82:             if (!proof.successful()) return J3TournamentCatalog.unavailable(
83:                     J3TournamentCatalogStatus.COLLECTION_NOT_COMPLETED, java.util.Optional.of(date()));
84:             var options = entries.stream().filter(Entry::eligible).map(Entry::option).toList();
85:             return J3TournamentCatalog.available(date(), proof.pages().stream().map(J3MinimizedPageEvidence::snapshotId).toList(),
86:                     options, entries.size() - options.size());
87:         }
88:     }
89:     public record Legacy(UUID campaignId, LocalDate date, Instant startedAt, Instant finishedAt,
90:                          int completedPages, int maximumPages, List<LegacyPage> pages) {
91:         public Legacy { pages = List.copyOf(pages); }
92:     }
93:     public record LegacyPage(int page, String requestKey, String source, String outcome, Long snapshotId,
94:                              String parserVersion, Instant resolvedAt, Long occurrenceId,
95:                              Instant requestedAt, Instant receivedAt, Long latencyMillis, String persistenceOutcome) { }
96:     public record DateSummary(LocalDate date, UUID runId, Instant completedAt, String recoveryStatus) { }
97:     public record CatalogPage(UUID runId,LocalDate date,Instant completedAt,int page,int pageSize,long total,List<Entry> entries) {
98:         public CatalogPage {entries=List.copyOf(entries);}
99:         public long pageCount() {return Math.max(1,(total+pageSize-1)/pageSize);}
100:     }
101: }
