12: /** Publish proof, catalogue, latest-success pointer, J8 terminal and order in one transaction. */
13: @Service
14: public class J3CollectionCompletionService {
15:     private final J3CollectionStore collections;private final J3AutomationStore orders;
16:     public J3CollectionCompletionService(J3CollectionStore collections,J3AutomationStore orders) {this.collections=collections;this.orders=orders;}
17:     public Optional<Proof> committedProof(UUID runId) {
18:         var order=orders.find(runId);
19:         return collections.find(runId).filter(c->order.isPresent()
20:                 && order.orElseThrow().state().name().equals(c.proof().state().name())
21:                 && Objects.equals(order.orElseThrow().reason(),c.proof().terminalCode())).map(c->c.proof());
22:     }
23:     @Transactional public void interrupt(UUID runId,Owner owner,java.time.Instant now,String reason) {
24:         collections.interrupt(runId,now,reason);
25:         orders.finish(runId,owner,OrderState.INTERRUPTED,reason,now);
26:     }
27:     @Transactional public void publish(Proof proof,List<Entry> entries,Owner owner,J8BenchmarkAuditService.Session audit) {
28:         collections.publish(proof,entries);
