325:         @Override public ScheduledEventsTransportResponse execute(ScheduledEventsProviderPageRequest request,Runnable dispatch) {
326:             check();
327:             String unavailable=providerUnavailableReason();
328:             if(unavailable!=null) throw new IllegalStateException(unavailable);
329:             if(lease==null) {
330:                 // No SQL transaction spans this bounded wait.
331:                 while(lease==null) {
332:                     check();
333:                     try {lease=coordinator.tryAcquireJ3Campaign(order.id());}
334:                     catch(ManualProviderRequestCoordinator.CoordinationException busy) {
335:                         if(!Instant.now().plusSeconds(130).isBefore(order.deadline())) throw busy;
336:                         try {Thread.sleep(100);} catch(InterruptedException interrupted) {
337:                             Thread.currentThread().interrupt();throw new PlaywrightDispatchCancelledException();
338:                         }
339:                     }
340:                 }
341:             }
342:             if(campaign==null) campaign=factory.open(order.id(),Set.of(SofascoreEndpointType.SCHEDULED_EVENTS));
