29:     }
30:     @PostMapping("/collect")
31:     public String collect(@RequestParam String localFormToken,@RequestParam UUID orderId,@RequestParam LocalDate date,
32:                           HttpSession session,RedirectAttributes flash) {
33:         tokens.consume(session,localFormToken);
34:         try {return "redirect:/j3/orders/"+runtime.manual(orderId,date,null).id();}
35:         catch(IllegalArgumentException | IllegalStateException failure) {return error(failure,flash,date);}
