79:         LocalDate target=null;
80:         try {
81:             target=planDate(date);
82:             runtime.schedule(ruleId,revision,target,planTime(at),planOffset(offset));
83:             flash.addFlashAttribute("j3Message","Horaire enregistré. Il sera exécuté si le laboratoire est en service et l’automatisation activée.");
84:             return "redirect:/#j3-automation";
85:         } catch(IllegalArgumentException | IllegalStateException failure) {
86:             return planError(failure,flash,input,target);
87:         } catch(InvalidDataAccessApiUsageException failure) {
88:             return planError(planRejection(failure),flash,input,target);
89:         }
90:     }
