92:     /** Only this submitted form is restored, including the rule/revision of an edited plan. */
93:     public record PlanInput(UUID ruleId,int revision,String date,String at,String offset) { }
94: 
95:     private static LocalDate planDate(String value) {
96:         if(value==null || value.isBlank())throw new IllegalArgumentException("J3_PLAN_DATE_REQUIRED");
97:         try {return LocalDate.parse(value);}
98:         catch(DateTimeException invalid) {throw new IllegalArgumentException("J3_PLAN_DATE_INVALID");}
99:     }
100:     private static LocalDateTime planTime(String value) {
101:         if(value==null || value.isBlank())throw new IllegalArgumentException("J3_PLAN_TIME_REQUIRED");
102:         try {return LocalDateTime.parse(value);}
103:         catch(DateTimeException invalid) {throw new IllegalArgumentException("J3_PLAN_TIME_INVALID");}
104:     }
105:     private static ZoneOffset planOffset(String value) {
106:         if(value==null || value.isBlank())return null;
107:         try {return ZoneOffset.of(value);}
108:         catch(DateTimeException invalid) {throw new IllegalArgumentException("J3_TIME_OFFSET_INVALID");}
109:     }
110:     private static RuntimeException planRejection(InvalidDataAccessApiUsageException failure) {
111:         // Spring's JPA translator also wraps argument/state rejections from the JDBC repository.
112:         // Recognize only the plan's business codes; unrelated persistence failures must propagate.
113:         Throwable cause=failure.getCause();
114:         if(cause instanceof IllegalArgumentException || cause instanceof IllegalStateException) {
115:             switch(String.valueOf(cause.getMessage())) {
116:                 case "J3_PLAN_MUST_BE_FUTURE","J3_PLAN_IDENTITY_CONFLICT","J3_PLAN_REVISION_CONFLICT",
117:                      "J3_PLAN_ALREADY_ADMITTED","J3_PLAN_LIMIT" -> {return (RuntimeException)cause;}
118:                 default -> { }
119:             }
120:         }
121:         throw failure;
122:     }
123:     private static String planError(RuntimeException failure,RedirectAttributes flash,PlanInput input,LocalDate date) {
124:         flash.addFlashAttribute("j3AutomationError",J3Presentation.reason(failure.getMessage()));
125:         flash.addFlashAttribute("j3PlanInput",input);
126:         return "redirect:/"+(date==null?"":"?j3Date="+date)+"#j3-automation";
127:     }
