146:                     "La collecte J3 est terminée : "+J3Presentation.state(order.state())+". "+J3Presentation.reason(order.reason()));
147:             return "redirect:/?j3Date="+order.date()+"#manual-call-control";
148:         }
149:         model.addAttribute("order",order);model.addAttribute("orderState",J3Presentation.state(order.state()));
150:         return "j3-order";
