111:             j3Transition(s,h,"QUIESCENT",null,List.of());
112:             publishStates(s);
113:             Supplier<String> cancelled=()-> s.stopReason!=null ? "LIVE_CAMPAIGN_STOPPED"
114:                     : !clock.instant().isBefore(h.deadline) ? "LIVE_J3_DEADLINE_EXPIRED" : null;
115:             var access=new J3CollectionExecutor.ProviderAccess() {
116:                 PlaywrightProviderCampaign scope;
117:                 boolean closed;
118:                 @Override public ScheduledEventsTransportResponse execute(ScheduledEventsProviderPageRequest request,Runnable dispatch) {
119:                     if(closed || cancelled.get()!=null) throw new PlaywrightDispatchCancelledException();
120:                     if(scope==null) {
121:                         scope=transport.openJ3SubOperation(new J3ProviderSubOperation(h.order.id(),h.order.date(),h.deadline));
122:                         j3Transition(s,h,"J3_ACTIVE",null,List.of());
123:                     }
124:                     var response=scope.execute(PlaywrightProviderRequest.scheduledEvents(request.date(),request.page()),
125:                         new PlaywrightDispatchAdmission() {
126:                             public void check() {
127:                                 if(cancelled.get()!=null || !guard.isOwned(s.ownership)) throw new PlaywrightDispatchCancelledException();
128:                             }
129:                             public Permit acquireDispatchPermit() {
130:                                 s.dispatchLock.lock();
131:                                 try { check();dispatch.run();return s.dispatchLock::unlock; }
132:                                 catch(RuntimeException failure) {s.dispatchLock.unlock();throw failure;}
133:                             }
134:                         });
135:                     return new ScheduledEventsTransportResponse(request.requestKey(),response.requestedAt(),response.receivedAt(),
136:                             response.httpStatus(),response.contentType().isBlank()?"application/octet-stream":response.contentType(),
137:                             response.latency(),response.payload());
138:                 }
139:                 @Override public void close() {
140:                     if(closed) return;
141:                     if(scope!=null) scope.close();
142:                     closed=true;
143:                 }
144:             };
