146:             try(access) { result=h.work.execute(access,cancelled); }
147:             // Publication failure, refusal, transport loss or uncertain context closure cannot resume live.
148:             s.dispatchLock.lock();
149:             try {
150:             if(!result.safeToResumeLive() || cancelled.get()!=null || !guard.isOwned(s.ownership)) {
